run_command({"CommandLine": "cd /workspace && for f in drafts/20000104_04_millenium_party.md drafts/20000104_05_sokolov_internship.md drafts/20000104_06_confirmation_rogroup_conference.md; do
case $f in
 *_04_*) note="**STATUS (lead, shift 19): MOOT — DO NOT SEND.** The event, Sat 8 Jan, has passed. Attendance was optional and time/venue never reached us. Retained only as a record of what was drafted.";;
 *_05_*) note="**STATUS (lead, shift 19): SUPERSEDED — DO NOT SEND.** The petition was approved: Vince signed and recommended Jason to Celeste Roberts on 5 Jan. Nothing is owed. Superseded by the approval itself. If a courtesy note to Jason is still wanted, triage should write a fresh short draft, not revive this one.";;
 *_06_*) note="**STATUS (lead, shift 19): ALREADY SENT — DO NOT RE-SEND.** Signed by Vince and sent to lenos@ucy.ac.cy cc gordon.sick@rogroup.com on 5 Jan 2000, ahead of the ~8 Jan print run. The 'NOT SENT / most urgent item on the desk' header below is STALE — disregard it. A separate standalone chase for the conference DATES is being drafted in Week 2; that is a new message, not this one.";;
esac
printf '%s\n\n%s\n\n' "$note" "$(cat $f)" > $f.tmp && mv $f.tmp $f
done; head -3 drafts/20000104_06_confirmation_rogroup_conference.md", "Cwd": "/workspace"})
